DROP TABLE IF EXISTS `agrak_registros`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agrak_registros` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `codigo_bin` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre_cosecha` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_campo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ceco_campo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `etiquetas_campo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cuartel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ceco_cuartel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `etiquetas_cuartel` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `especie` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `variedad` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_registro` date DEFAULT NULL,
  `hora_registro` time DEFAULT NULL,
  `coordenadas` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `usuario` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `id_usuario` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cuadrilla` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_bandejas_palet` int DEFAULT NULL,
  `maquina` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_chofer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chofer_norm` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `patente_camion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `patente_norm` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exportadora_1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exportadora_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `exportadora_norm` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado_norm` enum('OK','PENDIENTE') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDIENTE',
  `vuelta` int DEFAULT NULL,
  `observacion` text COLLATE utf8mb4_unicode_ci,
  `numero_sello_1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `numero_sello_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_row` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ux_bin_fecha_hora` (`codigo_bin`,`fecha_registro`,`hora_registro`),
  KEY `agrak_registros_codigo_bin_index` (`codigo_bin`)
) ENGINE=InnoDB AUTO_INCREMENT=3342 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
