DROP TABLE IF EXISTS `comfrut_guias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `comfrut_guias` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `guia_numero` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_guia` date DEFAULT NULL,
  `tipo_dte` varchar(5) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '52',
  `productor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rut_productor` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `patente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cantidad_total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `monto_total` int unsigned DEFAULT NULL,
  `xml_path` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `xml_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `comfrut_guias_guia_numero_unique` (`guia_numero`),
  UNIQUE KEY `comfrut_guias_xml_hash_unique` (`xml_hash`),
  KEY `comfrut_guias_guia_numero_index` (`guia_numero`),
  CONSTRAINT `comfrut_guias_chk_1` CHECK (json_valid(`meta`))
) ENGINE=InnoDB AUTO_INCREMENT=335 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
