DROP TABLE IF EXISTS `excel_out_transfers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `excel_out_transfers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `source_file` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `excel_row` int unsigned DEFAULT NULL,
  `contacto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_prevista` datetime DEFAULT NULL,
  `patente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `chofer` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `guia_entrega` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `import_key` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `prioridad` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referencia` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ubicacion_origen` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ubicacion_destino` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_traslado` datetime DEFAULT NULL,
  `documento_origen` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estado` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `archivo_dte` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `raw` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `excel_out_transfers_guia_entrega_index` (`guia_entrega`),
  KEY `excel_out_transfers_contacto_index` (`contacto`),
  KEY `excel_out_transfers_fecha_prevista_index` (`fecha_prevista`),
  KEY `excel_out_transfers_import_key_index` (`import_key`),
  CONSTRAINT `excel_out_transfers_chk_1` CHECK (json_valid(`raw`))
) ENGINE=InnoDB AUTO_INCREMENT=340 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
